uv-keyring = { version = "0.0.67", path = "crates/uv-keyring" }
uv-logging = { version = "0.0.67", path = "crates/uv-logging" }
uv-macros = { version = "0.0.67", path = "crates/uv-macros" }
uv-metadata = { version = "0.0.67", path = "crates/uv-metadata" }
uv-netrc = { version = "0.0.67", path = "crates/uv-netrc" }
uv-normalize = { version = "0.0.67", path = "crates/uv-normalize" }
