uv-torch = { version = "0.0.67", path = "crates/uv-torch" }
uv-trampoline-builder = { version = "0.0.67", path = "crates/uv-trampoline-builder" }
uv-types = { version = "0.0.67", path = "crates/uv-types" }
uv-unix = { version = "0.0.67", path = "crates/uv-unix" }
uv-version = { version = "0.12.0", path = "crates/uv-version" }
