[workspace.dependencies]
async-trait = "0.1.58"
atuin-client = { path = "crates/atuin-client", version = "18.18.1" }
atuin-common = { path = "crates/atuin-common", version = "18.18.1" }
atuin-daemon = { path = "crates/atuin-daemon", version = "18.18.1" }
atuin-domain = { path = "crates/atuin-domain", version = "18.18.1" }
atuin-dotfiles = { path = "crates/atuin-dotfiles", version = "18.18.1" }
atuin-history = { path = "crates/atuin-history", version = "18.18.1" }
atuin-kv = { path = "crates/atuin-kv", version = "18.18.1" }
atuin-scripts = { path = "crates/atuin-scripts", version = "18.18.1" }
atuin-server = { path = "crates/atuin-server", version = "18.18.1" }
atuin-server-database = { path = "crates/atuin-server-database", version = "18.18.1" }
atuin-server-postgres = { path = "crates/atuin-server-postgres", version = "18.18.1" }
atuin-server-sqlite = { path = "crates/atuin-server-sqlite", version = "18.18.1" }
atuin-nucleo = { path = "crates/atuin-nucleo", version = "0.6.0" }
atuin-nucleo-matcher = { path = "crates/atuin-nucleo/matcher", version = "0.3.1" }
base64 = "0.22"
crossterm = "0.29.0"
time = { version = "0.3.47", features = [
  "serde-human-readable",
  "macros",
  "local-offset",
] }
clap = { version = "4.5.7", features = ["derive"] }
config = { version = "0.15.8", default-features = false, features = ["toml"] }
derive_more = { version = "2", features = ["as_ref", "deref", "display", "error", "from", "into"] }
directories = "6.0.0"
eyre = "0.6"
fs-err = "3.1"
interim = { version = "0.2.0", features = ["time_0_3"] }
itertools = "0.14.0"
rand = { version = "0.8.5", features = ["std"] }
semver = "1.0.20"
serde = { version = "1.0.202", features = ["derive"] }
serde_json = "1.0.119"
shellexpand = "3"
tokio = { version = "1", features = ["full"] }
uuid = { version = "1.9", features = ["v4", "v7", "serde"] }
whoami = "2.1.0"
typed-builder = "0.23.2"
pretty_assertions = "1.3.0"
proptest = "1.11.0"
rstest = "0.26.1"
thiserror = "2"
rustix = { version = "1.1.4", features = ["process", "fs"] }
tower = "0.5"
tracing = "0.1"
tree-sitter = "0.26.8"
tree-sitter-bash = "0.25.1"
tree-sitter-fish = "3.6.0"
ratatui = "0.30.0"
sql-builder = "3"
tempfile = { version = "3.19" }
minijinja = "2.9.0"
rustls = { version = "0.23", default-features = false, features = [
  "ring",
  "std",
  "tls12",
] }
glob-match = "0.2.1"
imara-diff = "0.2"
xxhash-rust = { version = "0.8", features = ["xxh3"] }
vt100 = "0.16"
regex = "1.10.5"
toml_edit = "0.25.4"
url = { version = "2.5", features = ["serde"] }

[workspace.dependencies.tracing-subscriber]
version = "0.3"
features = ["ansi", "fmt", "registry", "env-filter", "json"]

[workspace.dependencies.reqwest]
version = "0.13"
features = ["json", "rustls-no-provider", "stream"]
default-features = false

[workspace.dependencies.sqlx]
version = "0.9"
features = ["runtime-tokio", "time", "uuid"]

# The profile that 'cargo dist' will build with
[profile.dist]
inherits = "release"
lto = "fat"
strip = "symbols"
codegen-units = 1

